#include <print>

int dayOfYear(int year, int month, int day) {
    int days[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    bool leap = (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
    int total = day;
    for (int m = 0; m < month - 1; ++m) {
        total += days[m];
        if (m == 1 && leap) total += 1;
    }
    return total;
}

int main() {
    std::println("2026-12-31 = {}，2028-12-31 = {}", dayOfYear(2026, 12, 31), dayOfYear(2028, 12, 31));
    return 0;
}

